 "content": "from collections import deque


def transform(grid):
    """Extend each colored patch along the length of its adjoining 5-bar."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bars = []

    # Find maximal straight runs of 5s, requiring length at least two.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            c0 = c
            while c < w and grid[r][c] == 5:
                c += 1
            if c - c0 >= 2:
                bars.append(("H", r, c0, c - 1))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            r0 = r
            while r < h and grid[r][c] == 5:
                r += 1
            if r - r0 >= 2:
                bars.append(("V", c, r0, r - 1))

    seen_global = set()
    for orient, fixed, start, end in bars:
        # Locate nonzero, non-5 cells touching either side of this bar.
        seeds = []
        for along in range(start, end + 1):
            if orient == "H":
                for rr in (fixed - 1, fixed + 1):
                    if 0 <= rr < h and grid[rr][along] not in (0, 5):
                        seeds.append((rr, along))
            else:
                for cc in (fixed - 1, fixed + 1):
                    if 0 <= cc < w and grid[along][cc] not in (0, 5):
                        seeds.append((along, cc))

        for seed in seeds:
            if seed in seen_global:
                continue
            # The attached non-background patch is the repeated template.
            q = deque([seed])
            comp = {seed}
            seen_global.add(seed)
            while q:
                r, c = q.popleft()
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] not in (0, 5) and
                            (nr, nc) not in seen_global):
                        seen_global.add((nr, nc))
                        comp.add((nr, nc))
                        q.append((nr, nc))
            rs = [p[0] for p in comp]
            cs = [p[1] for p in comp]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)

            # Tile the patch parallel to the bar. The original patch's top/left
            # edge fixes the phase when the pattern is extended in either way.
            if orient == "V":
                for r in range(start, end + 1):
                    pr = r0 + ((r - r0) % (r1 - r0 + 1))
                    for c in range(c0, c1 + 1):
                        if (pr, c) in comp:
                            out[r][c] = grid[pr][c]
            else:
                for r in range(r0, r1 + 1):
                    for c in range(start, end + 1):
                        pc = c0 + ((c - c0) % (c1 - c0 + 1))
                        if (r, pc) in comp:
                            out[r][c] = grid[r][pc]
    return out
